BEGIN;
CREATE TABLE IF NOT EXISTS marketing_journeys(id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT,automation_id INTEGER NOT NULL REFERENCES marketing_automations(id) ON DELETE RESTRICT,audience_config JSONB NOT NULL DEFAULT '{}',entry_criteria JSONB NOT NULL DEFAULT '{}',stages JSONB NOT NULL DEFAULT '[]',goals JSONB NOT NULL DEFAULT '[]',exit_conditions JSONB NOT NULL DEFAULT '[]',conversion_events JSONB NOT NULL DEFAULT '[]',status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','paused','archived')),version INTEGER NOT NULL DEFAULT 1,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_journey_members(id BIGSERIAL PRIMARY KEY,journey_id INTEGER NOT NULL REFERENCES marketing_journeys(id) ON DELETE CASCADE,marketing_contact_id INTEGER NOT NULL REFERENCES marketing_contacts(id) ON DELETE CASCADE,automation_execution_id UUID REFERENCES marketing_automation_executions(id) ON DELETE SET NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',entered_at TIMESTAMP DEFAULT NOW(),exited_at TIMESTAMP,goal_key VARCHAR(100),UNIQUE(journey_id,marketing_contact_id,status));
CREATE TABLE IF NOT EXISTS marketing_experiments(id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,experiment_type VARCHAR(30) NOT NULL CHECK(experiment_type IN('email','landing_page','cta','content_block')),audience_config JSONB NOT NULL DEFAULT '{}',conversion_event VARCHAR(80),status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','paused','completed','archived')),created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_experiment_variants(id SERIAL PRIMARY KEY,experiment_id INTEGER NOT NULL REFERENCES marketing_experiments(id) ON DELETE CASCADE,variant_key VARCHAR(30) NOT NULL,traffic_percent NUMERIC(5,2) NOT NULL CHECK(traffic_percent>0 AND traffic_percent<=100),content JSONB NOT NULL DEFAULT '{}',UNIQUE(experiment_id,variant_key));
CREATE TABLE IF NOT EXISTS marketing_experiment_assignments(experiment_id INTEGER NOT NULL REFERENCES marketing_experiments(id) ON DELETE CASCADE,subject_key VARCHAR(160) NOT NULL,variant_id INTEGER NOT NULL REFERENCES marketing_experiment_variants(id) ON DELETE CASCADE,assigned_at TIMESTAMP DEFAULT NOW(),PRIMARY KEY(experiment_id,subject_key));
CREATE TABLE IF NOT EXISTS marketing_experiment_events(id BIGSERIAL PRIMARY KEY,experiment_id INTEGER NOT NULL REFERENCES marketing_experiments(id) ON DELETE CASCADE,variant_id INTEGER NOT NULL REFERENCES marketing_experiment_variants(id) ON DELETE CASCADE,event_type VARCHAR(30) NOT NULL CHECK(event_type IN('view','send','click','conversion')),subject_key VARCHAR(160),occurred_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_attribution_touchpoints(id BIGSERIAL PRIMARY KEY,marketing_contact_id INTEGER REFERENCES marketing_contacts(id) ON DELETE CASCADE,visitor_id BIGINT REFERENCES marketing_visitors(id) ON DELETE CASCADE,event_id BIGINT REFERENCES marketing_events(id) ON DELETE SET NULL,touch_type VARCHAR(20) NOT NULL,source VARCHAR(160),medium VARCHAR(160),campaign VARCHAR(160),content VARCHAR(255),landing_page TEXT,referrer TEXT,occurred_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_conversions(id BIGSERIAL PRIMARY KEY,marketing_contact_id INTEGER REFERENCES marketing_contacts(id) ON DELETE SET NULL,visitor_id BIGINT REFERENCES marketing_visitors(id) ON DELETE SET NULL,event_id BIGINT REFERENCES marketing_events(id) ON DELETE SET NULL,conversion_type VARCHAR(80) NOT NULL,value NUMERIC(14,2),currency CHAR(3),occurred_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_mkt_touch_contact_time ON marketing_attribution_touchpoints(marketing_contact_id,occurred_at);
COMMIT;
